import React from 'react';
import { tvmConfig } from '../config/config';

export default function TvmResult({ plan, stbKey, onStbChange }) {
  const { setTopBoxes } = tvmConfig;
  const selectedBox = setTopBoxes[stbKey] || { pricing: {} };

  const terms      = Object.keys(plan.pricing);
  const planPrices = terms.map(term => plan.pricing[term]);
  const boxPrices  = terms.map(term => selectedBox.pricing[term] || 0);
  const totals     = planPrices.map((base, i) => base + boxPrices[i]);

  return (
    <div className="mb-8">
      <h2 className="text-xl font-semibold mb-4">
        선택된 지니TV : {plan.name} ({plan.channel}채널)
      </h2>

      <div className="mb-4">
        <label className="block mb-1 font-medium">셋톱박스 선택</label>
        <select
          className="w-full border rounded p-2"
          value={stbKey}
          onChange={e => onStbChange(e.target.value)}
        >
          <option value="">-- 셋톱박스 선택 --</option>
          {Object.entries(setTopBoxes).map(([key, box]) => (
            <option key={key} value={key}>{box.label}</option>
          ))}
        </select>
      </div>

      <table className="w-full table-auto border-collapse">
        <thead>
          <tr className="bg-gray-100">
            <th className="border px-3 py-2">약정 기간</th>
            {terms.map(term => <th key={term} className="border px-3 py-2">{term}</th>)}
          </tr>
        </thead>
        <tbody>
          <tr>
            <td className="border px-3 py-2">월 요금 (기본, VAT 포함)</td>
            {planPrices.map((price, i) => (
              <td key={i} className="border px-3 py-2">{price.toLocaleString()}</td>
            ))}
          </tr>
          <tr>
            <td className="border px-3 py-2">셋톱박스 (VAT 포함)</td>
            {boxPrices.map((price, i) => (
              <td key={i} className="border px-3 py-2">{price.toLocaleString()}</td>
            ))}
          </tr>
          <tr className="font-bold">
            <td className="border px-3 py-2">월 총금액 (VAT 포함)</td>
            {totals.map((total, i) => (
              <td key={i} className="border px-3 py-2">{total.toLocaleString()}</td>
            ))}
          </tr>
        </tbody>
      </table>
    </div>
  );
}